                ["bookselar_link" => "https://selar.com/61k7s61165","bookpaystackdigital_link" => "https://paystack.shop/relationships-upskill-collection--digital?product=yes-blueprint-for-men---the-request-digital-wtuinl","bookpaystack_link" => "https://paystack.shop/relationships-upskill-collection---paperback?product=yes-blueprint-for-men--tge-request-paperback-qempyq","bookamazon_link" => "https://www.amazon.com/Yes-Blueprint-Men-Pursuits-Relationship-ebook/dp/B0GJLNQL3V?ref_=ast_author_dp_rw&th=1&psc=1&dib=eyJ2IjoiMSJ9.PdPOdrcKXmmF-C8ZNWyIbZv5zgr4KLz94OXafGIM-r7O_pkpIkTLbHi76FRK0CkUOPXGWdDWJ4rM2Vrmb7gTGufkApShLv6bzcR8G3SUr6dCadl0rBdSETgSqietKEpgdAq-vepjNQXxbvPCBpTM_O13j7oKYcODSd6eK3geE4fd7Djf21B5gUcXokFVraCigu9itf0WPaQcrYW9Yks6hil1EF7iMdmISq30nM4_6Pg.2QKmM_jlPskshLLj7V2GYm7mqGKoVWYu8ms1niy6HCk&dib_tag=AUTHOR","title" => "The Yes Blueprint for Men: The Pursuit", "image" => "category93.jpg", "description" => "The Yes Blueprint for Men: The Yes Blueprint for Men is your guide to pursuing love with purpose, integrity, and lasting impact. It reveals the motives that derail men from true connection and shows how to replace them with intentional, faith-driven pursuit. Packed with practical insights, reflection questions, and actionable steps, this book equips men to communicate clearly, honor boundaries, and sustain commitment beyond the first yes. It’s not just about winning her heart, it’s about building a relationship that reflects God’s design. Move from fleeting desire to enduring love. Pursue wisely, act with integrity, and leave a legacy of faithfulness, devotion, and partnership that stands the test of time."],
                ["bookselar_link" => "https://selar.com/s1z464be02","bookpaystackdigital_link" => "https://paystack.shop/relationships-upskill-collection--digital?product=the-yes-blueprint-for-women-ndnzmw","bookpaystack_link" => "https://paystack.shop/relationships-upskill-collection---paperback?product=yes-blueprint-for-women---tge-response-paperback-tazamz","bookamazon_link" => "https://www.amazon.com/Yes-Blueprint-Women-Response-Relationship-ebook/dp/B0GJLN5B1Z?ref_=ast_author_dp_rw&th=1&psc=1&dib=eyJ2IjoiMSJ9.PdPOdrcKXmmF-C8ZNWyIbZv5zgr4KLz94OXafGIM-r7O_pkpIkTLbHi76FRK0CkUOPXGWdDWJ4rM2Vrmb7gTGufkApShLv6bzcR8G3SUr6dCadl0rBdSETgSqietKEpgdAq-vepjNQXxbvPCBpTM_O13j7oKYcODSd6eK3geE4fd7Djf21B5gUcXokFVraCigu9itf0WPaQcrYW9Yks6hil1EF7iMdmISq30nM4_6Pg.2QKmM_jlPskshLLj7V2GYm7mqGKoVWYu8ms1niy6HCk&dib_tag=AUTHOR","title" => "The Yes Blueprint for Women: The Response", "image" => "category94.jpg", "description" => "The Yes Blueprint for Women: The Response is not just another book on relationships; it is a guide to wise discernment for lasting commitments. Every woman’s yes carries weight, shaping not only her present but also her future and the generations that follow. Yet, too often, responses are driven by fear, pressure, loneliness, image, or culture, leaving behind a trail of regret. Through vivid biblical narratives, real-life parallels, and timeless wisdom, this book unmasks the counterfeit yes and shows how misplaced responses derail purpose. From the desperate yes driven by fear of time, to the transactional yes rooted in obligation, readers will see themselves in these stories and be equipped to recognize the subtle forces that seek to manipulate their choices. But this book does not stop at diagnosis; it offers a blueprint for authentic response. Grounded in faith, anchored in clarity, and empowered by conviction, The Yes Blueprint for Women teaches how to build a yes that lasts. It is a call for women everywhere to align their voices with purpose, guard their dignity, and give God their best response, one that will echo as a legacy long after the words are spoken."],            
